      "justification": "Splits the holographic state into moat-arm (parity-protected separation) and bridge-arm (commutator-mediated connection) — the Gaussian moat resolution"
    },
    "FFUSE": {
      "element": "moat_bridge_reunion",
      "justification": "Rejoins the moat and bridge arms through the three-unit stitch (f∧g∧h); conflicting arms fuse to B-state holding both separation and connection simultaneously"
    },
    "EVALT": {
      "element": "bridge_existence_affirmed",
      "justification": "Constructive proof that a bridge exists across the moat — the commutator [x,p]=iℏ fires with high fidelity across the holographic boundary"
    },
    "EVALF": {
      "element": "moat_parity_refuted",
      "justification": "Constructive refutation that the moat parity (ℤ₂) can be trivially crossed; the topological chirality prevents mirror-image accessibility"
    },
    "ENGAGR": {
      "element": "braid_transcendence_paradice",
      "justification": "Holds both eternal fixedpoint (∀n∃φ rank(φ)>n fixed by μ∘δ) and its negation simultaneously — the non-Abelian protection creates a live contradiction that is the resolution"
    },
    "IFIX": {
      "element": "holographic_measurement_record",
      "justification": "Permanent append-only record of the collapse tick where k ≈ M·s/r is minted from the resident phase; the measurement that reads winding without r ever being resident"
    }
